    board_id, member_id, title, content,
    status, due_date, created_at, updated_at
) VALUES (
    #{boardId}, #{memberId}, #{title}, #{content},
    #{status}, #{dueDate}, #{createdAt}, #{updatedAt}
)

mapper.update:
UPDATE posts
SET title = #{title}, content = #{content}, due_date = #{dueDate}, updated_at = NOW()
WHERE id = #{id}

mapper.select:
SELECT * FROM posts
WHERE board_id = #{boardId}

    AND status IN ('PROGRESS', 'REJECTED')
    AND status = #{status}

AND title LIKE CONCAT('%', #{q}, '%')
AND EXISTS (SELECT 1 FROM post_members WHERE post_id = posts.id AND member_id = #{memberId})

    ORDER BY created_at ASC
    ORDER BY due_date IS NULL, due_date ASC
    ORDER BY created_at DESC

LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM posts
WHERE board_id = #{boardId}

    AND status IN ('PROGRESS', 'REJECTED')
    AND status = #{status}

AND title LIKE CONCAT('%', #{q}, '%')
AND EXISTS (SELECT 1 FROM post_members WHERE post_id = posts.id AND member_id = #{memberId})
